{"code": "from datetime import date, timedelta

# England & Wales bank holidays (recording truck is based in Fraddon, Cornwall = England)
hols = {
    date(2022,12,26), date(2022,12,27),  # Boxing Day + Queen's State Funeral (extra hol)
    date(2023,1,2),   # substitute New Year's Day (1 Jan 2023 fell on a Sunday)
    date(2023,4,7), date(2023,4,10),     # Good Friday / Easter Monday
    date(2023,5,1), date(2023,5,29),
    date(2023,8,28), date(2023,12,25), date(2023,12,26)
}

def is_working_day(d):
    return d.weekday() < 5 and d not in hols

def nth_working_day_back(end, n):
    """return list of n working days ending at 'end' (inclusive), walking backwards"""
    days=[]
    d=end
    while len(days)<n:
        if is_working_day(d):
            days.append(d)
        d-=timedelta(days=1)
    return list(reversed(days))

results=[]
d=date(2023,1,1)
while d.year==2023:
    if d.weekday()==3:  # Thursday
        seq=nth_working_day_back(d,9)
        start=seq[0]
        results.append((d, start, start.weekday()==0, len(seq)))
    d+=timedelta(days=1)

for thu, start, ok, _ in results[:8]:
    print(f"Test Thursday {thu} -> 9th-working-day-back window starts {start} ({start.strftime('%A')})  valid Monday start? {ok}")

first_valid=[r for r in results if r[2]][0]
print("\nEarliest valid test date:", first_valid[0], first_valid[0].strftime('%A'))
print("Training window:", first_valid[1], "to", first_valid[0])"}

